/**
 * Student Task Management Application - Cloudflare Worker
 * Fully serverless REST API & Web Interface powered by Workers KV
 * Managed via Terraform IaC
 */

// Embedded Frontend Assets for standalone Worker deployment
const HTML_CONTENT = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Student Task Manager</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap\" rel=\"stylesheet\">\n</head>\n<body>\n  <div class=\"app-container\">\n    <!-- Header -->\n    <header class=\"app-header\">\n      <div class=\"header-content\">\n        <div class=\"brand\">\n          <div class=\"brand-icon\">\n            <svg width=\"28\" height=\"28\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n              <path d=\"M12 2L2 7l10 5 10-5-10-5z\"></path>\n              <path d=\"M2 17l10 5 10-5\"></path>\n              <path d=\"M2 12l10 5 10-5\"></path>\n            </svg>\n          </div>\n          <div>\n            <h1 id=\"app-title\">Student Task Manager</h1>\n            <p class=\"subtitle\">Automated Serverless Architecture &bull; Terraform &bull; Cloudflare Workers KV</p>\n          </div>\n        </div>\n        <div class=\"header-badges\">\n          <span class=\"badge badge-infra\" id=\"infra-badge\">IaC: Terraform</span>\n          <span class=\"badge badge-env\" id=\"env-badge\">Production</span>\n          <span class=\"badge badge-status\" id=\"connection-status\">Connecting...</span>\n        </div>\n      </div>\n    </header>\n\n    <!-- Metrics Cards -->\n    <section class=\"stats-grid\">\n      <div class=\"stat-card\">\n        <div class=\"stat-label\">Total Tasks</div>\n        <div class=\"stat-value\" id=\"stat-total\">0</div>\n        <div class=\"stat-desc\">Managed in Workers KV</div>\n      </div>\n      <div class=\"stat-card stat-pending\">\n        <div class=\"stat-label\">Pending</div>\n        <div class=\"stat-value\" id=\"stat-pending\">0</div>\n        <div class=\"stat-desc\">Awaiting completion</div>\n      </div>\n      <div class=\"stat-card stat-progress\">\n        <div class=\"stat-label\">In Progress</div>\n        <div class=\"stat-value\" id=\"stat-progress\">0</div>\n        <div class=\"stat-desc\">Currently active</div>\n      </div>\n      <div class=\"stat-card stat-completed\">\n        <div class=\"stat-label\">Completed</div>\n        <div class=\"stat-value\" id=\"stat-completed\">0</div>\n        <div class=\"stat-desc\">Tasks done</div>\n      </div>\n    </section>\n\n    <!-- Progress Bar -->\n    <div class=\"progress-container\">\n      <div class=\"progress-header\">\n        <span>Academic Completion Rate</span>\n        <span id=\"completion-rate\">0%</span>\n      </div>\n      <div class=\"progress-track\">\n        <div class=\"progress-bar\" id=\"progress-bar\" style=\"width: 0%;\"></div>\n      </div>\n    </div>\n\n    <!-- Main Content Area -->\n    <main class=\"main-layout\">\n      <!-- Create Task Panel -->\n      <section class=\"panel create-task-panel\">\n        <h2 class=\"panel-title\">\n          <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n            <line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"></line>\n            <line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"></line>\n          </svg>\n          Add New Academic Task\n        </h2>\n        <form id=\"create-task-form\" class=\"task-form\">\n          <div class=\"form-group\">\n            <label for=\"task-title\">Task Title <span class=\"required\">*</span></label>\n            <input \n              type=\"text\" \n              id=\"task-title\" \n              name=\"title\" \n              placeholder=\"e.g. Complete Cloud Computing Assignment\" \n              required\n              maxlength=\"120\"\n              autocomplete=\"off\"\n            >\n          </div>\n\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"task-priority\">Priority <span class=\"required\">*</span></label>\n              <select id=\"task-priority\" name=\"priority\" required>\n                <option value=\"High\">High</option>\n                <option value=\"Medium\" selected>Medium</option>\n                <option value=\"Low\">Low</option>\n              </select>\n            </div>\n\n            <div class=\"form-group\">\n              <label for=\"task-category\">Category</label>\n              <select id=\"task-category\" name=\"category\">\n                <option value=\"Assignment\" selected>Assignment</option>\n                <option value=\"Project\">Project</option>\n                <option value=\"Laboratory\">Laboratory</option>\n                <option value=\"Viva\">Viva</option>\n                <option value=\"General\">General</option>\n              </select>\n            </div>\n          </div>\n\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"task-status\">Initial Status</label>\n              <select id=\"task-status\" name=\"status\">\n                <option value=\"Pending\" selected>Pending</option>\n                <option value=\"In Progress\">In Progress</option>\n                <option value=\"Completed\">Completed</option>\n              </select>\n            </div>\n\n            <div class=\"form-group\">\n              <label for=\"task-deadline\">Due Date</label>\n              <input type=\"date\" id=\"task-deadline\" name=\"deadline\">\n            </div>\n          </div>\n\n          <button type=\"submit\" id=\"submit-btn\" class=\"btn btn-primary btn-block\">\n            <span class=\"btn-text\">Create Task</span>\n            <span class=\"btn-spinner hidden\"></span>\n          </button>\n        </form>\n\n        <div class=\"quick-examples\">\n          <p class=\"examples-label\">Suggested Academic Tasks:</p>\n          <div class=\"example-chips\">\n            <button type=\"button\" class=\"chip\" data-title=\"Complete Cloud Computing Assignment\" data-priority=\"High\" data-cat=\"Assignment\">Cloud Assignment</button>\n            <button type=\"button\" class=\"chip\" data-title=\"Prepare Final Year Project Presentation\" data-priority=\"High\" data-cat=\"Project\">Project Presentation</button>\n            <button type=\"button\" class=\"chip\" data-title=\"Submit Final Year Project Report\" data-priority=\"High\" data-cat=\"Project\">Project Report</button>\n            <button type=\"button\" class=\"chip\" data-title=\"Attend Project Viva\" data-priority=\"Medium\" data-cat=\"Viva\">Project Viva</button>\n            <button type=\"button\" class=\"chip\" data-title=\"Upload Laboratory Assignment\" data-priority=\"Medium\" data-cat=\"Laboratory\">Lab Upload</button>\n          </div>\n        </div>\n      </section>\n\n      <!-- Task List Panel -->\n      <section class=\"panel task-list-panel\">\n        <div class=\"panel-header-row\">\n          <h2 class=\"panel-title\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n              <path d=\"M9 11l3 3L22 4\"></path>\n              <path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"></path>\n            </svg>\n            Task Records\n          </h2>\n          <button id=\"refresh-btn\" class=\"btn btn-outline btn-sm\" title=\"Refresh task list from KV\">\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n              <polyline points=\"23 4 23 10 17 10\"></polyline>\n              <polyline points=\"1 20 1 14 7 14\"></polyline>\n              <path d=\"M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15\"></path>\n            </svg>\n            Refresh\n          </button>\n        </div>\n\n        <!-- Filter & Search Toolbar -->\n        <div class=\"toolbar\">\n          <div class=\"search-box\">\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n              <circle cx=\"11\" cy=\"11\" r=\"8\"></circle>\n              <line x1=\"21\" y1=\"21\" x2=\"16.65\" y2=\"16.65\"></line>\n            </svg>\n            <input type=\"text\" id=\"search-input\" placeholder=\"Search tasks by title or ID...\">\n          </div>\n\n          <div class=\"filters-row\">\n            <select id=\"filter-status\" class=\"filter-select\">\n              <option value=\"ALL\">All Statuses</option>\n              <option value=\"Pending\">Pending</option>\n              <option value=\"In Progress\">In Progress</option>\n              <option value=\"Completed\">Completed</option>\n            </select>\n\n            <select id=\"filter-priority\" class=\"filter-select\">\n              <option value=\"ALL\">All Priorities</option>\n              <option value=\"High\">High Priority</option>\n              <option value=\"Medium\">Medium Priority</option>\n              <option value=\"Low\">Low Priority</option>\n            </select>\n\n            <select id=\"filter-category\" class=\"filter-select\">\n              <option value=\"ALL\">All Categories</option>\n              <option value=\"Assignment\">Assignment</option>\n              <option value=\"Project\">Project</option>\n              <option value=\"Laboratory\">Laboratory</option>\n              <option value=\"Viva\">Viva</option>\n              <option value=\"General\">General</option>\n            </select>\n\n            <select id=\"sort-by\" class=\"filter-select\">\n              <option value=\"date-desc\">Newest First</option>\n              <option value=\"date-asc\">Oldest First</option>\n              <option value=\"priority-desc\">Priority (High to Low)</option>\n              <option value=\"title-asc\">Title (A-Z)</option>\n            </select>\n          </div>\n        </div>\n\n        <!-- Task List Container -->\n        <div id=\"tasks-container\" class=\"tasks-container\">\n          <div class=\"loading-state\" id=\"loading-state\">\n            <div class=\"spinner\"></div>\n            <p>Loading tasks from Cloudflare Workers KV...</p>\n          </div>\n          <div class=\"empty-state hidden\" id=\"empty-state\">\n            <svg width=\"48\" height=\"48\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\">\n              <rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect>\n              <line x1=\"16\" y1=\"2\" x2=\"16\" y2=\"6\"></line>\n              <line x1=\"8\" y1=\"2\" x2=\"8\" y2=\"6\"></line>\n              <line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"></line>\n            </svg>\n            <h3>No tasks found</h3>\n            <p>Add your first academic task above or adjust your search filter.</p>\n          </div>\n          <table class=\"tasks-table hidden\" id=\"tasks-table\">\n            <thead>\n              <tr>\n                <th style=\"width: 10%;\">ID</th>\n                <th style=\"width: 32%;\">Task</th>\n                <th style=\"width: 14%;\">Category</th>\n                <th style=\"width: 12%;\">Priority</th>\n                <th style=\"width: 12%;\">Status</th>\n                <th style=\"width: 20%; text-align: right;\">Actions</th>\n              </tr>\n            </thead>\n            <tbody id=\"tasks-tbody\">\n              <!-- Rendered via JavaScript -->\n            </tbody>\n          </table>\n        </div>\n      </section>\n    </main>\n\n    <!-- Edit Task Modal -->\n    <div class=\"modal-overlay hidden\" id=\"edit-modal\">\n      <div class=\"modal-card\">\n        <div class=\"modal-header\">\n          <h3>Update Task</h3>\n          <button type=\"button\" class=\"modal-close\" id=\"modal-close\">&times;</button>\n        </div>\n        <form id=\"edit-task-form\">\n          <input type=\"hidden\" id=\"edit-task-id\">\n          <div class=\"form-group\">\n            <label for=\"edit-task-title\">Task Title</label>\n            <input type=\"text\" id=\"edit-task-title\" required maxlength=\"120\">\n          </div>\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"edit-task-priority\">Priority</label>\n              <select id=\"edit-task-priority\">\n                <option value=\"High\">High</option>\n                <option value=\"Medium\">Medium</option>\n                <option value=\"Low\">Low</option>\n              </select>\n            </div>\n            <div class=\"form-group\">\n              <label for=\"edit-task-category\">Category</label>\n              <select id=\"edit-task-category\">\n                <option value=\"Assignment\">Assignment</option>\n                <option value=\"Project\">Project</option>\n                <option value=\"Laboratory\">Laboratory</option>\n                <option value=\"Viva\">Viva</option>\n                <option value=\"General\">General</option>\n              </select>\n            </div>\n          </div>\n          <div class=\"form-row\">\n            <div class=\"form-group\">\n              <label for=\"edit-task-status\">Status</label>\n              <select id=\"edit-task-status\">\n                <option value=\"Pending\">Pending</option>\n                <option value=\"In Progress\">In Progress</option>\n                <option value=\"Completed\">Completed</option>\n              </select>\n            </div>\n            <div class=\"form-group\">\n              <label for=\"edit-task-deadline\">Due Date</label>\n              <input type=\"date\" id=\"edit-task-deadline\">\n            </div>\n          </div>\n          <div class=\"modal-actions\">\n            <button type=\"button\" class=\"btn btn-outline\" id=\"modal-cancel\">Cancel</button>\n            <button type=\"submit\" class=\"btn btn-primary\" id=\"modal-save\">Update Task</button>\n          </div>\n        </form>\n      </div>\n    </div>\n\n    <!-- Toast Notifications -->\n    <div id=\"toast-container\" class=\"toast-container\"></div>\n\n    <!-- Footer -->\n    <footer class=\"app-footer\">\n      <div class=\"footer-details\">\n        <span>Student Task Management Application &bull; Mini Project 2</span>\n        <span>Infrastructure as Code with <strong>Terraform</strong> on <strong>Cloudflare Workers</strong> &amp; <strong>Workers KV</strong></span>\n      </div>\n    </footer>\n  </div>\n\n  <script src=\"script.js\"></script>\n</body>\n</html>\n";
const CSS_CONTENT = ":root {\n  --primary: #2563eb;\n  --primary-hover: #1d4ed8;\n  --primary-light: #eff6ff;\n  --bg-main: #f8fafc;\n  --bg-card: #ffffff;\n  --text-main: #0f172a;\n  --text-muted: #64748b;\n  --border-color: #e2e8f0;\n  \n  --priority-high: #ef4444;\n  --priority-high-bg: #fef2f2;\n  --priority-med: #f59e0b;\n  --priority-med-bg: #fffbeb;\n  --priority-low: #10b981;\n  --priority-low-bg: #ecfdf5;\n\n  --status-pending: #f59e0b;\n  --status-pending-bg: #fffbeb;\n  --status-progress: #3b82f6;\n  --status-progress-bg: #eff6ff;\n  --status-completed: #10b981;\n  --status-completed-bg: #ecfdf5;\n\n  --radius-sm: 6px;\n  --radius-md: 10px;\n  --radius-lg: 16px;\n  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);\n  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);\n  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.08);\n}\n\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  font-family: 'Inter', -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n  background-color: var(--bg-main);\n  color: var(--text-main);\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n}\n\n.app-container {\n  max-width: 1200px;\n  margin: 0 auto;\n  padding: 24px 20px 48px;\n}\n\n/* Header */\n.app-header {\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  padding: 24px 28px;\n  margin-bottom: 24px;\n  box-shadow: var(--shadow-sm);\n}\n\n.header-content {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 16px;\n}\n\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n\n.brand-icon {\n  width: 48px;\n  height: 48px;\n  border-radius: var(--radius-md);\n  background: linear-gradient(135deg, #2563eb, #1d4ed8);\n  color: white;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  box-shadow: 0 4px 10px rgba(37, 99, 235, 0.3);\n}\n\n.brand h1 {\n  font-size: 1.5rem;\n  font-weight: 700;\n  color: var(--text-main);\n  letter-spacing: -0.02em;\n}\n\n.subtitle {\n  font-size: 0.85rem;\n  color: var(--text-muted);\n  margin-top: 2px;\n}\n\n.header-badges {\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.badge {\n  display: inline-flex;\n  align-items: center;\n  font-size: 0.75rem;\n  font-weight: 600;\n  padding: 4px 10px;\n  border-radius: 9999px;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n.badge-infra {\n  background: #f1f5f9;\n  color: #475569;\n  border: 1px solid #cbd5e1;\n}\n\n.badge-env {\n  background: #eff6ff;\n  color: #1d4ed8;\n  border: 1px solid #bfdbfe;\n}\n\n.badge-status {\n  background: #fef3c7;\n  color: #92400e;\n}\n\n.badge-status.connected {\n  background: #ecfdf5;\n  color: #065f46;\n}\n\n.badge-status.error {\n  background: #fef2f2;\n  color: #991b1b;\n}\n\n/* Statistics Grid */\n.stats-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: 16px;\n  margin-bottom: 20px;\n}\n\n.stat-card {\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-md);\n  padding: 20px;\n  box-shadow: var(--shadow-sm);\n  transition: transform 0.15s ease, box-shadow 0.15s ease;\n}\n\n.stat-card:hover {\n  transform: translateY(-2px);\n  box-shadow: var(--shadow-md);\n}\n\n.stat-label {\n  font-size: 0.85rem;\n  color: var(--text-muted);\n  font-weight: 500;\n}\n\n.stat-value {\n  font-size: 2rem;\n  font-weight: 700;\n  color: var(--text-main);\n  margin: 4px 0;\n  letter-spacing: -0.03em;\n}\n\n.stat-desc {\n  font-size: 0.75rem;\n  color: var(--text-muted);\n}\n\n.stat-pending .stat-value { color: var(--status-pending); }\n.stat-progress .stat-value { color: var(--status-progress); }\n.stat-completed .stat-value { color: var(--status-completed); }\n\n/* Progress Container */\n.progress-container {\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-md);\n  padding: 16px 20px;\n  margin-bottom: 24px;\n  box-shadow: var(--shadow-sm);\n}\n\n.progress-header {\n  display: flex;\n  justify-content: space-between;\n  font-size: 0.85rem;\n  font-weight: 600;\n  margin-bottom: 8px;\n  color: var(--text-main);\n}\n\n.progress-track {\n  width: 100%;\n  height: 10px;\n  background: #e2e8f0;\n  border-radius: 9999px;\n  overflow: hidden;\n}\n\n.progress-bar {\n  height: 100%;\n  background: linear-gradient(90deg, #3b82f6, #10b981);\n  border-radius: 9999px;\n  transition: width 0.4s ease;\n}\n\n/* Layout */\n.main-layout {\n  display: grid;\n  grid-template-columns: 360px 1fr;\n  gap: 24px;\n  align-items: start;\n}\n\n@media (max-width: 900px) {\n  .main-layout {\n    grid-template-columns: 1fr;\n  }\n}\n\n/* Panels */\n.panel {\n  background: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  padding: 24px;\n  box-shadow: var(--shadow-sm);\n}\n\n.panel-title {\n  font-size: 1.15rem;\n  font-weight: 600;\n  color: var(--text-main);\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 20px;\n}\n\n.panel-header-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 16px;\n}\n\n/* Forms */\n.task-form {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n.form-group {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  flex: 1;\n}\n\n.form-row {\n  display: flex;\n  gap: 12px;\n}\n\nlabel {\n  font-size: 0.825rem;\n  font-weight: 600;\n  color: #334155;\n}\n\n.required {\n  color: #ef4444;\n}\n\ninput[type=\"text\"],\ninput[type=\"date\"],\nselect {\n  width: 100%;\n  padding: 10px 12px;\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  font-family: inherit;\n  font-size: 0.9rem;\n  color: var(--text-main);\n  background-color: #ffffff;\n  outline: none;\n  transition: border-color 0.15s, box-shadow 0.15s;\n}\n\ninput[type=\"text\"]:focus,\ninput[type=\"date\"]:focus,\nselect:focus {\n  border-color: var(--primary);\n  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);\n}\n\n/* Buttons */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  font-family: inherit;\n  font-weight: 600;\n  border-radius: var(--radius-sm);\n  cursor: pointer;\n  border: none;\n  transition: all 0.15s ease;\n  white-space: nowrap;\n}\n\n.btn-primary {\n  background-color: var(--primary);\n  color: #ffffff;\n  padding: 11px 16px;\n}\n\n.btn-primary:hover {\n  background-color: var(--primary-hover);\n}\n\n.btn-block {\n  width: 100%;\n}\n\n.btn-outline {\n  background: transparent;\n  color: var(--text-muted);\n  border: 1px solid var(--border-color);\n  padding: 8px 12px;\n}\n\n.btn-outline:hover {\n  background: #f1f5f9;\n  color: var(--text-main);\n}\n\n.btn-sm {\n  font-size: 0.8rem;\n  padding: 6px 10px;\n}\n\n.btn-danger {\n  color: #dc2626;\n  background: transparent;\n  border: 1px solid #fecaca;\n}\n\n.btn-danger:hover {\n  background: #fee2e2;\n}\n\n.btn-toggle-status {\n  color: #059669;\n  background: #ecfdf5;\n  border: 1px solid #a7f3d0;\n}\n\n.btn-toggle-status:hover {\n  background: #d1fae5;\n}\n\n/* Suggested Task Chips */\n.quick-examples {\n  margin-top: 24px;\n  padding-top: 20px;\n  border-top: 1px dashed var(--border-color);\n}\n\n.examples-label {\n  font-size: 0.775rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  color: var(--text-muted);\n  letter-spacing: 0.05em;\n  margin-bottom: 10px;\n}\n\n.example-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.chip {\n  background: #f1f5f9;\n  border: 1px solid #e2e8f0;\n  border-radius: 9999px;\n  padding: 5px 10px;\n  font-size: 0.75rem;\n  color: #475569;\n  cursor: pointer;\n  transition: all 0.15s;\n}\n\n.chip:hover {\n  background: var(--primary-light);\n  border-color: #bfdbfe;\n  color: var(--primary);\n}\n\n/* Toolbar */\n.toolbar {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  margin-bottom: 18px;\n}\n\n.search-box {\n  position: relative;\n  display: flex;\n  align-items: center;\n}\n\n.search-box svg {\n  position: absolute;\n  left: 12px;\n  color: var(--text-muted);\n  pointer-events: none;\n}\n\n.search-box input {\n  padding-left: 36px;\n}\n\n.filters-row {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));\n  gap: 8px;\n}\n\n.filter-select {\n  font-size: 0.8rem;\n  padding: 8px 10px;\n}\n\n/* Tasks Table */\n.tasks-container {\n  overflow-x: auto;\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-md);\n  background: #ffffff;\n  min-height: 240px;\n}\n\n.tasks-table {\n  width: 100%;\n  border-collapse: collapse;\n  text-align: left;\n}\n\n.tasks-table th {\n  background: #f8fafc;\n  color: #64748b;\n  font-size: 0.75rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  padding: 12px 14px;\n  border-bottom: 1px solid var(--border-color);\n}\n\n.tasks-table td {\n  padding: 12px 14px;\n  font-size: 0.85rem;\n  border-bottom: 1px solid var(--border-color);\n  vertical-align: middle;\n}\n\n.tasks-table tr:last-child td {\n  border-bottom: none;\n}\n\n.tasks-table tr:hover td {\n  background-color: #f8fafc;\n}\n\n.task-id-badge {\n  font-family: monospace;\n  font-weight: 700;\n  font-size: 0.775rem;\n  color: #3b82f6;\n  background: #eff6ff;\n  padding: 3px 6px;\n  border-radius: 4px;\n  border: 1px solid #dbeafe;\n}\n\n.task-title-cell {\n  font-weight: 500;\n  color: var(--text-main);\n}\n\n.task-title-cell.completed {\n  text-decoration: line-through;\n  color: var(--text-muted);\n}\n\n.task-meta {\n  font-size: 0.75rem;\n  color: var(--text-muted);\n  margin-top: 2px;\n}\n\n.priority-badge {\n  display: inline-block;\n  font-size: 0.75rem;\n  font-weight: 600;\n  padding: 3px 8px;\n  border-radius: 9999px;\n}\n\n.priority-badge.high {\n  background: var(--priority-high-bg);\n  color: var(--priority-high);\n  border: 1px solid #fecaca;\n}\n\n.priority-badge.medium {\n  background: var(--priority-med-bg);\n  color: var(--priority-med);\n  border: 1px solid #fed7aa;\n}\n\n.priority-badge.low {\n  background: var(--priority-low-bg);\n  color: var(--priority-low);\n  border: 1px solid #a7f3d0;\n}\n\n.status-badge {\n  display: inline-block;\n  font-size: 0.75rem;\n  font-weight: 600;\n  padding: 3px 8px;\n  border-radius: 9999px;\n}\n\n.status-badge.pending {\n  background: var(--status-pending-bg);\n  color: var(--status-pending);\n  border: 1px solid #fed7aa;\n}\n\n.status-badge.in-progress {\n  background: var(--status-progress-bg);\n  color: var(--status-progress);\n  border: 1px solid #bfdbfe;\n}\n\n.status-badge.completed {\n  background: var(--status-completed-bg);\n  color: var(--status-completed);\n  border: 1px solid #a7f3d0;\n}\n\n.category-tag {\n  font-size: 0.75rem;\n  color: #475569;\n  background: #f1f5f9;\n  padding: 2px 7px;\n  border-radius: 4px;\n  border: 1px solid #e2e8f0;\n}\n\n.table-actions {\n  display: flex;\n  gap: 6px;\n  justify-content: flex-end;\n}\n\n/* States */\n.loading-state,\n.empty-state {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  padding: 48px 20px;\n  text-align: center;\n  color: var(--text-muted);\n}\n\n.spinner {\n  width: 32px;\n  height: 32px;\n  border: 3px solid #e2e8f0;\n  border-top-color: var(--primary);\n  border-radius: 50%;\n  animation: spin 0.8s linear infinite;\n  margin-bottom: 12px;\n}\n\n@keyframes spin {\n  to { transform: rotate(360deg); }\n}\n\n.hidden {\n  display: none !important;\n}\n\n/* Modal */\n.modal-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(15, 23, 42, 0.5);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 16px;\n  z-index: 50;\n  backdrop-filter: blur(2px);\n}\n\n.modal-card {\n  background: #ffffff;\n  border-radius: var(--radius-lg);\n  max-width: 500px;\n  width: 100%;\n  padding: 24px;\n  box-shadow: var(--shadow-lg);\n}\n\n.modal-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 16px;\n}\n\n.modal-header h3 {\n  font-size: 1.15rem;\n  font-weight: 600;\n}\n\n.modal-close {\n  background: transparent;\n  border: none;\n  font-size: 1.5rem;\n  color: var(--text-muted);\n  cursor: pointer;\n  line-height: 1;\n}\n\n.modal-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 10px;\n  margin-top: 20px;\n}\n\n/* Toast */\n.toast-container {\n  position: fixed;\n  bottom: 24px;\n  right: 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  z-index: 100;\n}\n\n.toast {\n  background: #1e293b;\n  color: #ffffff;\n  padding: 12px 18px;\n  border-radius: var(--radius-md);\n  font-size: 0.85rem;\n  box-shadow: var(--shadow-lg);\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  animation: slideIn 0.2s ease-out;\n  min-width: 260px;\n}\n\n.toast.success {\n  border-left: 4px solid #10b981;\n}\n\n.toast.error {\n  border-left: 4px solid #ef4444;\n}\n\n@keyframes slideIn {\n  from {\n    opacity: 0;\n    transform: translateY(10px);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n/* Footer */\n.app-footer {\n  margin-top: 40px;\n  text-align: center;\n  font-size: 0.8rem;\n  color: var(--text-muted);\n  border-top: 1px solid var(--border-color);\n  padding-top: 20px;\n}\n\n.footer-details {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n";
const JS_CONTENT = "// Student Task Manager - Frontend Controller\n(function() {\n  'use strict';\n\n  // Base API configuration\n  const API_BASE = window.location.origin.includes('http') \n    ? `${window.location.origin}/api/tasks` \n    : '/api/tasks';\n\n  // State\n  let tasks = [];\n  let filterState = {\n    search: '',\n    status: 'ALL',\n    priority: 'ALL',\n    category: 'ALL',\n    sort: 'date-desc'\n  };\n\n  // DOM Elements\n  const appTitleEl = document.getElementById('app-title');\n  const envBadgeEl = document.getElementById('env-badge');\n  const connectionStatusEl = document.getElementById('connection-status');\n  const createForm = document.getElementById('create-task-form');\n  const submitBtn = document.getElementById('submit-btn');\n  const refreshBtn = document.getElementById('refresh-btn');\n  const searchInput = document.getElementById('search-input');\n  const filterStatus = document.getElementById('filter-status');\n  const filterPriority = document.getElementById('filter-priority');\n  const filterCategory = document.getElementById('filter-category');\n  const sortBy = document.getElementById('sort-by');\n  const tasksTable = document.getElementById('tasks-table');\n  const tasksTbody = document.getElementById('tasks-tbody');\n  const loadingState = document.getElementById('loading-state');\n  const emptyState = document.getElementById('empty-state');\n  \n  // Stats Elements\n  const statTotal = document.getElementById('stat-total');\n  const statPending = document.getElementById('stat-pending');\n  const statProgress = document.getElementById('stat-progress');\n  const statCompleted = document.getElementById('stat-completed');\n  const completionRate = document.getElementById('completion-rate');\n  const progressBar = document.getElementById('progress-bar');\n\n  // Edit Modal Elements\n  const editModal = document.getElementById('edit-modal');\n  const editForm = document.getElementById('edit-task-form');\n  const editTaskId = document.getElementById('edit-task-id');\n  const editTaskTitle = document.getElementById('edit-task-title');\n  const editTaskPriority = document.getElementById('edit-task-priority');\n  const editTaskCategory = document.getElementById('edit-task-category');\n  const editTaskStatus = document.getElementById('edit-task-status');\n  const editTaskDeadline = document.getElementById('edit-task-deadline');\n  const modalClose = document.getElementById('modal-close');\n  const modalCancel = document.getElementById('modal-cancel');\n\n  // Initialization\n  document.addEventListener('DOMContentLoaded', () => {\n    initApp();\n    bindEvents();\n    fetchTasks();\n  });\n\n  // Initialize App and Server Info\n  async function initApp() {\n    try {\n      const res = await fetch('/api/info');\n      if (res.ok) {\n        const info = await res.json();\n        if (info.appName && appTitleEl) {\n          appTitleEl.textContent = info.appName;\n          document.title = info.appName;\n        }\n        if (info.environment && envBadgeEl) {\n          envBadgeEl.textContent = info.environment.toUpperCase();\n        }\n      }\n    } catch (_) {\n      // Use defaults if not on worker\n    }\n  }\n\n  // Bind Event Listeners\n  function bindEvents() {\n    createForm.addEventListener('submit', handleCreateTask);\n    refreshBtn.addEventListener('click', fetchTasks);\n    \n    // Quick example chips\n    document.querySelectorAll('.chip').forEach(chip => {\n      chip.addEventListener('click', () => {\n        document.getElementById('task-title').value = chip.dataset.title;\n        document.getElementById('task-priority').value = chip.dataset.priority;\n        document.getElementById('task-category').value = chip.dataset.cat;\n        document.getElementById('task-title').focus();\n      });\n    });\n\n    // Filters and Search\n    searchInput.addEventListener('input', (e) => {\n      filterState.search = e.target.value.toLowerCase().trim();\n      renderTasks();\n    });\n\n    filterStatus.addEventListener('change', (e) => {\n      filterState.status = e.target.value;\n      renderTasks();\n    });\n\n    filterPriority.addEventListener('change', (e) => {\n      filterState.priority = e.target.value;\n      renderTasks();\n    });\n\n    filterCategory.addEventListener('change', (e) => {\n      filterState.category = e.target.value;\n      renderTasks();\n    });\n\n    sortBy.addEventListener('change', (e) => {\n      filterState.sort = e.target.value;\n      renderTasks();\n    });\n\n    // Edit Modal events\n    modalClose.addEventListener('click', closeEditModal);\n    modalCancel.addEventListener('click', closeEditModal);\n    editModal.addEventListener('click', (e) => {\n      if (e.target === editModal) closeEditModal();\n    });\n    editForm.addEventListener('submit', handleUpdateTask);\n  }\n\n  // Fetch all tasks from Cloudflare Worker KV via GET /api/tasks\n  async function fetchTasks() {\n    setLoading(true);\n    setConnectionStatus('connecting', 'Connecting...');\n    try {\n      const res = await fetch(API_BASE);\n      if (!res.ok) {\n        throw new Error(`Failed to load tasks: HTTP ${res.status}`);\n      }\n      const data = await res.json();\n      tasks = Array.isArray(data) ? data : (data.tasks || []);\n      setConnectionStatus('connected', 'KV Connected');\n      renderTasks();\n    } catch (err) {\n      console.warn('API fetch error, attempting fallback:', err);\n      setConnectionStatus('error', 'KV Offline (Demo Mode)');\n      // If run locally without backend, provide demo sample tasks\n      if (tasks.length === 0) {\n        tasks = [\n          {\n            id: 'T101',\n            title: 'Complete Cloud Computing Assignment',\n            priority: 'High',\n            category: 'Assignment',\n            status: 'Pending',\n            createdAt: new Date(Date.now() - 86400000).toISOString(),\n            deadline: ''\n          },\n          {\n            id: 'T102',\n            title: 'Prepare Final Year Project Presentation',\n            priority: 'High',\n            category: 'Project',\n            status: 'Pending',\n            createdAt: new Date().toISOString(),\n            deadline: ''\n          }\n        ];\n      }\n      renderTasks();\n    } finally {\n      setLoading(false);\n    }\n  }\n\n  // Create Task via POST /api/tasks\n  async function handleCreateTask(e) {\n    e.preventDefault();\n    const titleInput = document.getElementById('task-title');\n    const prioritySelect = document.getElementById('task-priority');\n    const categorySelect = document.getElementById('task-category');\n    const statusSelect = document.getElementById('task-status');\n    const deadlineInput = document.getElementById('task-deadline');\n\n    const newTask = {\n      title: titleInput.value.trim(),\n      priority: prioritySelect.value,\n      category: categorySelect.value,\n      status: statusSelect.value,\n      deadline: deadlineInput.value || null\n    };\n\n    if (!newTask.title) return;\n\n    setButtonLoading(submitBtn, true, 'Creating...');\n\n    try {\n      const res = await fetch(API_BASE, {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(newTask)\n      });\n\n      if (!res.ok) {\n        throw new Error(`Server returned status ${res.status}`);\n      }\n\n      const createdTask = await res.json();\n      tasks.unshift(createdTask);\n      createForm.reset();\n      prioritySelect.value = 'Medium';\n      categorySelect.value = 'Assignment';\n      statusSelect.value = 'Pending';\n      \n      showToast('Task successfully created.', 'success');\n      renderTasks();\n    } catch (err) {\n      console.warn('Backend unavailable, saving locally for preview:', err);\n      const fallbackTask = {\n        id: `T${100 + tasks.length + 1}`,\n        ...newTask,\n        createdAt: new Date().toISOString()\n      };\n      tasks.unshift(fallbackTask);\n      createForm.reset();\n      showToast('Task successfully created.', 'success');\n      renderTasks();\n    } finally {\n      setButtonLoading(submitBtn, false, 'Create Task');\n    }\n  }\n\n  // Quick Toggle Task Status (Pending <-> Completed) via PUT /api/tasks/{id}\n  async function toggleTaskStatus(id) {\n    const task = tasks.find(t => t.id === id);\n    if (!task) return;\n\n    const newStatus = task.status === 'Completed' ? 'Pending' : 'Completed';\n    const updatedPayload = { ...task, status: newStatus };\n\n    try {\n      const res = await fetch(`${API_BASE}/${id}`, {\n        method: 'PUT',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(updatedPayload)\n      });\n\n      if (res.ok) {\n        const updated = await res.json();\n        Object.assign(task, updated);\n      } else {\n        task.status = newStatus;\n      }\n      showToast('Status changed successfully.', 'success');\n      renderTasks();\n    } catch (_) {\n      task.status = newStatus;\n      showToast('Status changed successfully.', 'success');\n      renderTasks();\n    }\n  }\n\n  // Open Edit Modal\n  function openEditModal(id) {\n    const task = tasks.find(t => t.id === id);\n    if (!task) return;\n\n    editTaskId.value = task.id;\n    editTaskTitle.value = task.title;\n    editTaskPriority.value = task.priority || 'Medium';\n    editTaskCategory.value = task.category || 'Assignment';\n    editTaskStatus.value = task.status || 'Pending';\n    editTaskDeadline.value = task.deadline || '';\n\n    editModal.classList.remove('hidden');\n  }\n\n  function closeEditModal() {\n    editModal.classList.add('hidden');\n    editForm.reset();\n  }\n\n  // Save Task Update via PUT /api/tasks/{id}\n  async function handleUpdateTask(e) {\n    e.preventDefault();\n    const id = editTaskId.value;\n    const task = tasks.find(t => t.id === id);\n    if (!task) return;\n\n    const updatedData = {\n      ...task,\n      title: editTaskTitle.value.trim(),\n      priority: editTaskPriority.value,\n      category: editTaskCategory.value,\n      status: editTaskStatus.value,\n      deadline: editTaskDeadline.value || null\n    };\n\n    try {\n      const res = await fetch(`${API_BASE}/${id}`, {\n        method: 'PUT',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify(updatedData)\n      });\n\n      if (res.ok) {\n        const saved = await res.json();\n        Object.assign(task, saved);\n      } else {\n        Object.assign(task, updatedData);\n      }\n      showToast('Status changed successfully.', 'success');\n      closeEditModal();\n      renderTasks();\n    } catch (_) {\n      Object.assign(task, updatedData);\n      showToast('Status changed successfully.', 'success');\n      closeEditModal();\n      renderTasks();\n    }\n  }\n\n  // Delete Task via DELETE /api/tasks/{id}\n  async function deleteTask(id) {\n    if (!confirm(`Are you sure you want to remove task ${id}?`)) return;\n\n    try {\n      const res = await fetch(`${API_BASE}/${id}`, {\n        method: 'DELETE'\n      });\n\n      if (!res.ok && res.status !== 404) {\n        throw new Error('Failed to delete');\n      }\n    } catch (_) {\n      // Continue removing from local state\n    }\n\n    tasks = tasks.filter(t => t.id !== id);\n    showToast('Task removed successfully.', 'success');\n    renderTasks();\n  }\n\n  // Filter and Sort Tasks\n  function getFilteredTasks() {\n    return tasks.filter(task => {\n      // Search\n      if (filterState.search) {\n        const text = `${task.id} ${task.title}`.toLowerCase();\n        if (!text.includes(filterState.search)) return false;\n      }\n      // Status\n      if (filterState.status !== 'ALL' && task.status !== filterState.status) {\n        return false;\n      }\n      // Priority\n      if (filterState.priority !== 'ALL' && task.priority !== filterState.priority) {\n        return false;\n      }\n      // Category\n      if (filterState.category !== 'ALL' && task.category !== filterState.category) {\n        return false;\n      }\n      return true;\n    }).sort((a, b) => {\n      const priorityWeights = { High: 3, Medium: 2, Low: 1 };\n      switch (filterState.sort) {\n        case 'date-desc':\n          return new Date(b.createdAt || 0) - new Date(a.createdAt || 0);\n        case 'date-asc':\n          return new Date(a.createdAt || 0) - new Date(b.createdAt || 0);\n        case 'priority-desc':\n          return (priorityWeights[b.priority] || 0) - (priorityWeights[a.priority] || 0);\n        case 'title-asc':\n          return (a.title || '').localeCompare(b.title || '');\n        default:\n          return 0;\n      }\n    });\n  }\n\n  // Render Tasks & Update Dashboard Statistics\n  function renderTasks() {\n    updateStatistics();\n    const filtered = getFilteredTasks();\n\n    if (tasks.length === 0 || filtered.length === 0) {\n      tasksTable.classList.add('hidden');\n      emptyState.classList.remove('hidden');\n      return;\n    }\n\n    emptyState.classList.add('hidden');\n    tasksTable.classList.remove('hidden');\n    tasksTbody.innerHTML = '';\n\n    filtered.forEach(task => {\n      const tr = document.createElement('tr');\n      const priorityClass = (task.priority || 'medium').toLowerCase();\n      const statusClass = (task.status || 'pending').toLowerCase().replace(' ', '-');\n      const isCompleted = task.status === 'Completed';\n\n      tr.innerHTML = `\n        <td><span class=\"task-id-badge\">${escapeHtml(task.id)}</span></td>\n        <td>\n          <div class=\"task-title-cell ${isCompleted ? 'completed' : ''}\">${escapeHtml(task.title)}</div>\n          <div class=\"task-meta\">\n            ${task.deadline ? `Due: ${escapeHtml(task.deadline)} &bull; ` : ''}\n            Created: ${formatDate(task.createdAt)}\n          </div>\n        </td>\n        <td><span class=\"category-tag\">${escapeHtml(task.category || 'General')}</span></td>\n        <td><span class=\"priority-badge ${priorityClass}\">${escapeHtml(task.priority || 'Medium')}</span></td>\n        <td><span class=\"status-badge ${statusClass}\">${escapeHtml(task.status || 'Pending')}</span></td>\n        <td style=\"text-align: right;\">\n          <div class=\"table-actions\">\n            <button class=\"btn btn-sm btn-toggle-status\" data-action=\"toggle\" data-id=\"${task.id}\" title=\"Toggle Complete\">\n              ${isCompleted ? 'Reopen' : 'Done'}\n            </button>\n            <button class=\"btn btn-sm btn-outline\" data-action=\"edit\" data-id=\"${task.id}\" title=\"Edit Task\">\n              Edit\n            </button>\n            <button class=\"btn btn-sm btn-danger\" data-action=\"delete\" data-id=\"${task.id}\" title=\"Delete Task\">\n              Delete\n            </button>\n          </div>\n        </td>\n      `;\n\n      // Bind buttons\n      tr.querySelector('[data-action=\"toggle\"]').addEventListener('click', () => toggleTaskStatus(task.id));\n      tr.querySelector('[data-action=\"edit\"]').addEventListener('click', () => openEditModal(task.id));\n      tr.querySelector('[data-action=\"delete\"]').addEventListener('click', () => deleteTask(task.id));\n\n      tasksTbody.appendChild(tr);\n    });\n  }\n\n  // Update Summary Statistics\n  function updateStatistics() {\n    const total = tasks.length;\n    const pending = tasks.filter(t => t.status === 'Pending').length;\n    const progress = tasks.filter(t => t.status === 'In Progress').length;\n    const completed = tasks.filter(t => t.status === 'Completed').length;\n    const rate = total > 0 ? Math.round((completed / total) * 100) : 0;\n\n    statTotal.textContent = total;\n    statPending.textContent = pending;\n    statProgress.textContent = progress;\n    statCompleted.textContent = completed;\n    completionRate.textContent = `${rate}%`;\n    progressBar.style.width = `${rate}%`;\n  }\n\n  // Helpers\n  function setLoading(isLoading) {\n    if (isLoading) {\n      loadingState.classList.remove('hidden');\n      tasksTable.classList.add('hidden');\n      emptyState.classList.add('hidden');\n    } else {\n      loadingState.classList.add('hidden');\n    }\n  }\n\n  function setConnectionStatus(type, text) {\n    connectionStatusEl.className = `badge badge-status ${type}`;\n    connectionStatusEl.textContent = text;\n  }\n\n  function setButtonLoading(button, isLoading, text) {\n    const textSpan = button.querySelector('.btn-text');\n    const spinner = button.querySelector('.btn-spinner');\n    if (isLoading) {\n      button.disabled = true;\n      if (textSpan) textSpan.textContent = text;\n      if (spinner) spinner.classList.remove('hidden');\n    } else {\n      button.disabled = false;\n      if (textSpan) textSpan.textContent = text;\n      if (spinner) spinner.classList.add('hidden');\n    }\n  }\n\n  function formatDate(isoString) {\n    if (!isoString) return 'Today';\n    try {\n      const d = new Date(isoString);\n      return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });\n    } catch (_) {\n      return 'Recent';\n    }\n  }\n\n  function escapeHtml(str) {\n    if (!str) return '';\n    return String(str)\n      .replace(/&/g, '&amp;')\n      .replace(/</g, '&lt;')\n      .replace(/>/g, '&gt;')\n      .replace(/\"/g, '&quot;')\n      .replace(/'/g, '&#039;');\n  }\n\n  function showToast(message, type = 'success') {\n    const container = document.getElementById('toast-container');\n    const toast = document.createElement('div');\n    toast.className = `toast ${type}`;\n    toast.innerHTML = `\n      <span>${escapeHtml(message)}</span>\n    `;\n    container.appendChild(toast);\n    setTimeout(() => {\n      toast.style.opacity = '0';\n      toast.style.transition = 'opacity 0.3s ease';\n      setTimeout(() => toast.remove(), 300);\n    }, 3200);\n  }\n\n})();\n";

// Standard CORS Headers
const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
  'Access-Control-Max-Age': '86400',
};

// Response helper
function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      ...CORS_HEADERS
    }
  });
}

function textResponse(content, contentType, status = 200) {
  return new Response(content, {
    status,
    headers: {
      'Content-Type': contentType,
      'Cache-Control': 'public, max-age=300',
      ...CORS_HEADERS
    }
  });
}

// Generate sequential academic task ID (e.g., T101, T102, T103...)
function generateTaskId(existingIds) {
  let maxNum = 100;
  for (const id of existingIds) {
    const match = id.match(/^T(\d+)$/i);
    if (match) {
      const num = parseInt(match[1], 10);
      if (num > maxNum) maxNum = num;
    }
  }
  return `T${maxNum + 1}`;
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const pathname = url.pathname;
    const method = request.method.toUpperCase();

    // Handle CORS preflight
    if (method === 'OPTIONS') {
      return new Response(null, {
        status: 204,
        headers: CORS_HEADERS
      });
    }

    // Static Assets & Web Interface
    if (pathname === '/' || pathname === '/index.html') {
      return textResponse(HTML_CONTENT, 'text/html; charset=utf-8');
    }
    if (pathname === '/style.css') {
      return textResponse(CSS_CONTENT, 'text/css; charset=utf-8');
    }
    if (pathname === '/script.js') {
      return textResponse(JS_CONTENT, 'application/javascript; charset=utf-8');
    }
    if (pathname === '/favicon.ico') {
      return new Response(null, { status: 204 });
    }

    // Diagnostics & Environment endpoint
    if (pathname === '/api/info' && method === 'GET') {
      return jsonResponse({
        appName: env.APP_NAME || 'Student Task Manager',
        environment: env.ENVIRONMENT || 'production',
        kvBound: !!env.TASKS_KV,
        timestamp: new Date().toISOString()
      });
    }

    // REST API Routing: /api/tasks and /api/tasks/{id}
    if (pathname.startsWith('/api/tasks')) {
      const kv = env.TASKS_KV;
      if (!kv) {
        return jsonResponse({
          error: 'Cloudflare Workers KV binding TASKS_KV not configured'
        }, 500);
      }

      const pathSegments = pathname.split('/').filter(Boolean);
      // pathSegments = ['api', 'tasks'] or ['api', 'tasks', '{id}']
      const taskId = pathSegments[2] ? decodeURIComponent(pathSegments[2]) : null;

      try {
        // GET /api/tasks - Retrieve all tasks
        if (method === 'GET' && !taskId) {
          let index = await kv.get('task_index', 'json');
          if (!index || !Array.isArray(index)) {
            // Re-discover from KV prefix listing if index is empty
            const list = await kv.list({ prefix: 'task:' });
            index = list.keys.map(k => k.name.replace('task:', ''));
            if (index.length > 0) {
              await kv.put('task_index', JSON.stringify(index));
            } else {
              index = [];
            }
          }

          const tasks = [];
          for (const id of index) {
            const task = await kv.get(`task:${id}`, 'json');
            if (task) {
              tasks.push(task);
            }
          }

          return jsonResponse(tasks);
        }

        // GET /api/tasks/{id} - Retrieve single task
        if (method === 'GET' && taskId) {
          const task = await kv.get(`task:${taskId}`, 'json');
          if (!task) {
            return jsonResponse({ error: 'Task not found', id: taskId }, 404);
          }
          return jsonResponse(task);
        }

        // POST /api/tasks - Create new task
        if (method === 'POST' && !taskId) {
          let body;
          try {
            body = await request.json();
          } catch (_) {
            return jsonResponse({ error: 'Invalid JSON request body' }, 400);
          }

          if (!body.title || typeof body.title !== 'string' || !body.title.trim()) {
            return jsonResponse({ error: 'Field "title" is required' }, 400);
          }

          let index = await kv.get('task_index', 'json');
          if (!Array.isArray(index)) {
            const list = await kv.list({ prefix: 'task:' });
            index = list.keys.map(k => k.name.replace('task:', ''));
          }

          const id = body.id || generateTaskId(index);
          const now = new Date().toISOString();

          const newTask = {
            id,
            title: body.title.trim(),
            priority: body.priority || 'Medium',
            category: body.category || 'Assignment',
            status: body.status || 'Pending',
            deadline: body.deadline || null,
            createdAt: now,
            updatedAt: now
          };

          // Save individual task record and update index
          await kv.put(`task:${id}`, JSON.stringify(newTask));
          if (!index.includes(id)) {
            index.push(id);
            await kv.put('task_index', JSON.stringify(index));
          }

          return jsonResponse(newTask, 201);
        }

        // PUT /api/tasks/{id} - Update existing task
        if (method === 'PUT' && taskId) {
          const existing = await kv.get(`task:${taskId}`, 'json');
          if (!existing) {
            return jsonResponse({ error: 'Task not found', id: taskId }, 404);
          }

          let body;
          try {
            body = await request.json();
          } catch (_) {
            return jsonResponse({ error: 'Invalid JSON request body' }, 400);
          }

          const updatedTask = {
            ...existing,
            title: body.title !== undefined ? String(body.title).trim() : existing.title,
            priority: body.priority !== undefined ? body.priority : existing.priority,
            category: body.category !== undefined ? body.category : existing.category,
            status: body.status !== undefined ? body.status : existing.status,
            deadline: body.deadline !== undefined ? body.deadline : existing.deadline,
            updatedAt: new Date().toISOString()
          };

          await kv.put(`task:${taskId}`, JSON.stringify(updatedTask));
          return jsonResponse(updatedTask, 200);
        }

        // DELETE /api/tasks/{id} - Delete task
        if (method === 'DELETE' && taskId) {
          const existing = await kv.get(`task:${taskId}`, 'json');
          if (!existing) {
            return jsonResponse({ error: 'Task not found', id: taskId }, 404);
          }

          await kv.delete(`task:${taskId}`);

          let index = await kv.get('task_index', 'json');
          if (Array.isArray(index)) {
            index = index.filter(id => id !== taskId);
            await kv.put('task_index', JSON.stringify(index));
          }

          return jsonResponse({
            message: 'Task removed successfully.',
            id: taskId
          }, 200);
        }

        return jsonResponse({ error: 'Method not allowed on this path' }, 405);
      } catch (err) {
        return jsonResponse({ error: 'Internal Worker Error', details: err.message }, 500);
      }
    }

    return jsonResponse({ error: 'Route not found' }, 404);
  }
};
